-- Alt text for the header images carried over from v1, which had none.
-- Alchemy re-imports this file only when it changes, so alt text edited in
-- the admin afterwards stays put unless this file is edited again.
UPDATE media SET alt = 'A giant blue alien with red eyes peers down at a tiny human girl sitting in the palm of its hand.' WHERE key = 'images/fantastic-planet.webp';
UPDATE media SET alt = 'Stitch bursts out of a mound of red dirt, grinning with his arms raised, in front of palm trees and purple mountains.' WHERE key = 'images/lilo-and-stitch.webp';
UPDATE media SET alt = 'A painting of Gandalf, his long white beard and grey cloak whipping in the wind, pointing a glowing finger at the sky with one hand on a sword.' WHERE key = 'images/lord-of-the-rings.webp';
UPDATE media SET alt = 'Pinky and the Brain, two white lab mice, stand on top of the globe on either side of a giant red horseshoe magnet, with stars and Saturn behind them.' WHERE key = 'images/pinky-and-the-brain.webp';
UPDATE media SET alt = 'Four black-and-white cartoon skeletons dance arm in arm through a graveyard.' WHERE key = 'images/skeleton-dance.webp';
UPDATE media SET alt = 'Long John Silver reaches his mechanical arm out into a starry blue nebula, his other arm around a grinning Jim Hawkins, both perched on the golden yardarm of a ship.' WHERE key = 'images/treasure-planet.webp';
